CREATE COLUMN TABLE "TEST_AP"."OPQW" ("AbsEntry" INTEGER CS_INT NOT NULL , "SetName" NVARCHAR(20) NOT NULL , "SetDesc" NVARCHAR(100), "CreateDate" LONGDATE CS_LONGDATE, "ModifyDate" LONGDATE CS_LONGDATE, "UserSign" SMALLINT CS_INT, "CreatDraft" NVARCHAR(1) DEFAULT 'N', "GroupBy" NVARCHAR(1) DEFAULT 'B', "ValidUntil" LONGDATE CS_LONGDATE, "BPLId" INTEGER CS_INT, "ReqDate" LONGDATE CS_LONGDATE, "BaseOn" NVARCHAR(1), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OPQW_SET_NAME" ON "TEST_AP"."OPQW" ( "SetName" ASC )